  'mejora.sobredescuento.desc': {es:'DESCUENTO AL ABRIR CUALQUIER SOBRE DE FICHAJES', en:'DISCOUNT WHEN OPENING ANY TRANSFER ENVELOPE', pt:'DESCONTO AO ABRIR QUALQUER ENVELOPE DE CONTRATAÇÕES', fr:'REDUCTION A OUVERTURE DE TOUTE ENVELOPPE DE TRANSFERT', de:'RABATT BEIM OFFNEN JEDES TRANSFER-UMSCHLAGS', it:'SCONTO ALLAPERTURA DI QUALSIASI BUSTA DI TRATTATIVE'},
  'mejora.sin_descuento': {es:'Sin descuento', en:'No discount', pt:'Sem desconto', fr:'Aucune reduction', de:'Kein Rabatt', it:'Nessuno sconto'},
  'mejora.sobredescuento.tooltip': {es:'{n}% de descuento al abrir sobres', en:'{n}% discount when opening envelopes', pt:'{n}% de desconto ao abrir envelopes', fr:'{n}% de reduction a ouverture des enveloppes', de:'{n}% Rabatt beim Offnen von Umschlagen', it:'{n}% di sconto allapertura delle buste'},

  /* Habilidades */
  'skill.categoria_tactica': {es:'TÁCTICA', en:'TACTICS', pt:'TÁTICA', fr:'TACTIQUE', de:'TAKTIK', it:'TATTICA'},
  'skill.categoria_gestion': {es:'GESTIÓN', en:'MANAGEMENT', pt:'GESTÃO', fr:'GESTION', de:'MANAGEMENT', it:'GESTIONE'},
  'skill.mentalidad_ganadora.nombre': {es:'MENTALIDAD GANADORA', en:'WINNING MINDSET', pt:'MENTALIDADE VENCEDORA', fr:'MENTALITE DE GAGNANT', de:'SIEGERMENTALITAT', it:'MENTALITA VINCENTE'},
  'skill.mentalidad_ganadora.tooltip': {es:'Tras 3 victorias seguidas, tu equipo sale con un pequeño extra de ataque en el siguiente partido.', en:'After 3 wins in a row, your team gets a small attack boost in the next match.', pt:'Após 3 vitórias seguidas, a sua equipa sai com um pequeno extra de ataque no próximo jogo.', fr:'Apres 3 victoires de suite, ton equipe beneficie d un petit bonus d attaque au prochain match.', de:'Nach 3 Siegen in Folge erhalt dein Team im nachsten Spiel einen kleinen Angriffsbonus.', it:'Dopo 3 vittorie di fila, la tua squadra parte con un piccolo extra di attacco nella prossima partita.'},
  'skill.revancha.nombre': {es:'REVANCHA', en:'REVENGE', pt:'REVANCHE', fr:'REVANCHE', de:'REVANCHE', it:'RIVINCITA'},
  'skill.revancha.tooltip': {es:'Tras perder el partido anterior, tu equipo sale con un pequeño extra de ataque para resarcirse.', en:'After losing the previous match, your team gets a small attack boost to make up for it.', pt:'Após perder o jogo anterior, a sua equipa sai com um pequeno extra de ataque para se desforrar.', fr:'Apres avoir perdu le match precedent, ton equipe beneficie d un petit bonus d attaque pour se racheter.', de:'Nach einer Niederlage im vorherigen Spiel erhalt dein Team einen kleinen Angriffsbonus zur Wiedergutmachung.', it:'Dopo aver perso la partita precedente, la tua squadra parte con un piccolo extra di attacco per rifarsi.'},
  'skill.factor_campo.nombre': {es:'FACTOR CAMPO', en:'HOME ADVANTAGE', pt:'FATOR CAMPO', fr:'FACTEUR TERRAIN', de:'HEIMVORTEIL', it:'FATTORE CAMPO'},
  'skill.factor_campo.tooltip': {es:'Jugando como local, tu equipo rinde ligeramente mejor.', en:'Playing at home, your team performs slightly better.', pt:'Jogando em casa, a sua equipa rende ligeiramente melhor.', fr:'En jouant a domicile, ton equipe est legerement meilleure.', de:'Im Heimspiel spielt dein Team etwas besser.', it:'Giocando in casa, la tua squadra rende leggermente meglio.'},
  'skill.meteorologo.nombre': {es:'ESPECIALISTA EN CLIMA', en:'WEATHER SPECIALIST', pt:'ESPECIALISTA EM CLIMA', fr:'SPECIALISTE METEO', de:'WETTERSPEZIALIST', it:'SPECIALISTA DEL METEO'},
  'skill.meteorologo.tooltip': {es:'Reduce a la mitad la penalización que sufre tu equipo por la lluvia, el viento, el calor o la nieve.', en:'Halves the penalty your team suffers from rain, wind, heat or snow.', pt:'Reduz para metade a penalização que a sua equipa sofre por chuva, vento, calor ou neve.', fr:'Reduit de moitie la penalite subie par ton equipe a cause de la pluie, du vent, de la chaleur ou de la neige.', de:'Halbiert die Strafe deines Teams durch Regen, Wind, Hitze oder Schnee.', it:'Dimezza la penalita subita dalla tua squadra per pioggia, vento, caldo o neve.'},
  'skill.temple_competitivo.nombre': {es:'TEMPLE COMPETITIVO', en:'COMPETITIVE SPIRIT', pt:'TEMPERAMENTO COMPETITIVO', fr:'ESPRIT COMPETITIF', de:'WETTKAMPFGEIST', it:'TEMPRA COMPETITIVA'},
  'skill.temple_competitivo.tooltip': {es:'Pierdes menos moral cuando el partido se decide por la mínima.', en:'You lose less morale when the match is decided by the narrowest margin.', pt:'Perde menos moral quando o jogo se decide pela margem mínima.', fr:'Tu perds moins de moral quand le match se joue a un but pres.', de:'Du verlierst weniger Moral, wenn das Spiel knapp entschieden wird.', it:'Perdi meno morale quando la partita si decide per il minimo scarto.'},
  'skill.contraataque_letal.nombre': {es:'CONTRAATAQUE LETAL', en:'LETHAL COUNTERATTACK', pt:'CONTRA-ATAQUE LETAL', fr:'CONTRE-ATTAQUE LETALE', de:'TODLICHER KONTERANGRIFF', it:'CONTROATTACCO LETALE'},
  'skill.contraataque_letal.tooltip': {es:'Jugando como visitante, tu equipo defiende ligeramente mejor.', en:'Playing away, your team defends slightly better.', pt:'Jogando fora, a sua equipa defende ligeiramente melhor.', fr:'En jouant a l exterieur, ton equipe defend legerement mieux.', de:'Im Auswartsspiel verteidigt dein Team etwas besser.', it:'Giocando fuori casa, la tua squadra difende leggermente meglio.'},

