  'welcome.register': {es:'REGÍSTRATE', en:'SIGN UP', pt:'REGISTRE-SE', fr:'S\'INSCRIRE', de:'REGISTRIEREN', it:'REGISTRATI'},
  'welcome.apk_banner': {
    es:'Para una mejor experiencia en tu dispositivo móvil, <a href="downloads/Goal2Goat.apk" download style="color:var(--gold);font-weight:700;text-decoration:underline">descarga la APK desde aquí</a>.',
    en:'For a better experience on your mobile device, <a href="downloads/Goal2Goat.apk" download style="color:var(--gold);font-weight:700;text-decoration:underline">download the APK here</a>.',
    pt:'Para uma melhor experiência no seu dispositivo móvel, <a href="downloads/Goal2Goat.apk" download style="color:var(--gold);font-weight:700;text-decoration:underline">baixe o APK aqui</a>.',
    fr:'Pour une meilleure expérience sur votre appareil mobile, <a href="downloads/Goal2Goat.apk" download style="color:var(--gold);font-weight:700;text-decoration:underline">téléchargez l\'APK ici</a>.',
    de:'Für ein besseres Erlebnis auf deinem Mobilgerät, <a href="downloads/Goal2Goat.apk" download style="color:var(--gold);font-weight:700;text-decoration:underline">lade hier die APK herunter</a>.',
    it:'Per un\'esperienza migliore sul tuo dispositivo mobile, <a href="downloads/Goal2Goat.apk" download style="color:var(--gold);font-weight:700;text-decoration:underline">scarica l\'APK qui</a>.'
  },
  'welcome.text_guest': {
    es:'Bienvenido a <strong style="color:var(--gold)">Goal2Goat</strong>, <strong style="color:var(--gold)">REGÍSTRATE</strong> para guardar tu progreso y tener acceso a contenido exclusivo.<br><br>Goal2Goat es un manager de fútbol con alma de roguelike. Tu apoyo nos ayuda a seguir mejorando el juego, añadiendo contenido nuevo y manteniéndolo libre de publicidad invasiva.',
    en:'Welcome to <strong style="color:var(--gold)">Goal2Goat</strong> — <strong style="color:var(--gold)">SIGN UP</strong> to save your progress and access exclusive content.<br><br>Goal2Goat is a football manager with a roguelike soul. Your support helps us keep improving the game, adding new content and keeping it free from intrusive ads.',
    pt:'Bem-vindo ao <strong style="color:var(--gold)">Goal2Goat</strong> — <strong style="color:var(--gold)">REGISTRE-SE</strong> para guardar seu progresso e acessar conteúdo exclusivo.<br><br>Goal2Goat é um manager de futebol com alma de roguelike. Seu apoio nos ajuda a continuar melhorando o jogo, adicionando novo conteúdo e mantendo-o livre de anúncios invasivos.',
    fr:'Bienvenue sur <strong style="color:var(--gold)">Goal2Goat</strong> — <strong style="color:var(--gold)">INSCRIVEZ-VOUS</strong> pour sauvegarder votre progression et accéder au contenu exclusif.<br><br>Goal2Goat est un manager de football avec une âme de roguelike. Votre soutien nous aide à améliorer le jeu, à ajouter du nouveau contenu et à le garder sans publicité.',
    de:'Willkommen bei <strong style="color:var(--gold)">Goal2Goat</strong> — <strong style="color:var(--gold)">REGISTRIERE DICH</strong>, um deinen Fortschritt zu speichern und auf exklusive Inhalte zuzugreifen.<br><br>Goal2Goat ist ein Fußballmanager mit Roguelike-Seele. Deine Unterstützung hilft uns, das Spiel zu verbessern, neue Inhalte hinzuzufügen und es frei von aufdringlicher Werbung zu halten.',
    it:'Benvenuto su <strong style="color:var(--gold)">Goal2Goat</strong> — <strong style="color:var(--gold)">REGISTRATI</strong> per salvare i tuoi progressi e accedere ai contenuti esclusivi.<br><br>Goal2Goat è un manager di calcio con un\'anima da roguelike. Il tuo supporto ci aiuta a continuare a migliorare il gioco, ad aggiungere nuovi contenuti e a mantenerlo privo di pubblicità invasiva.'
  },
  'welcome.text_user': {
    es:'Bienvenido a <strong style="color:var(--gold)">Goal2Goat</strong>, un manager de fútbol con alma de roguelike. Tu apoyo nos ayuda a seguir mejorando el juego, añadiendo contenido nuevo y manteniéndolo libre de publicidad invasiva.',
    en:'Welcome to <strong style="color:var(--gold)">Goal2Goat</strong>, a football manager with a roguelike soul. Your support helps us keep improving the game, adding new content and keeping it free from intrusive ads.',
    pt:'Bem-vindo ao <strong style="color:var(--gold)">Goal2Goat</strong>, um manager de futebol com alma de roguelike. Seu apoio nos ajuda a continuar melhorando o jogo, adicionando novo conteúdo e mantendo-o livre de anúncios invasivos.',
    fr:'Bienvenue sur <strong style="color:var(--gold)">Goal2Goat</strong>, un manager de football avec une âme de roguelike. Votre soutien nous aide à améliorer le jeu, à ajouter du nouveau contenu et à le garder sans publicité.',
    de:'Willkommen bei <strong style="color:var(--gold)">Goal2Goat</strong>, einem Fußballmanager mit Roguelike-Seele. Deine Unterstützung hilft uns, das Spiel zu verbessern, neue Inhalte hinzuzufügen und es frei von aufdringlicher Werbung zu halten.',
    it:'Benvenuto su <strong style="color:var(--gold)">Goal2Goat</strong>, un manager di calcio con un\'anima da roguelike. Il tuo supporto ci aiuta a continuare a migliorare il gioco, ad aggiungere nuovi contenuti e a mantenerlo privo di pubblicità invasiva.'
  },
