  'strategy.posesion.desc': {es:'Mantiene el control del balón para dominar el ritmo del partido.', en:'Keeps control of the ball to dominate the tempo of the match.', pt:'Mantém o controle da bola para dominar o ritmo da partida.', fr:'Garde le contrôle du ballon pour dominer le rythme du match.', de:'Behält die Ballkontrolle, um das Spieltempo zu dominieren.', it:'Mantiene il controllo del pallone per dominare il ritmo della partita.'},
