  'hud.next_rival': {es:'PRÓXIMO RIVAL', en:'NEXT OPPONENT', pt:'PRÓXIMO RIVAL', fr:'PROCHAIN ADVERSAIRE', de:'NÄCHSTER GEGNER', it:'PROSSIMO AVVERSARIO'},
